<?php
require_once dirname(__DIR__).'/services/PeriodReviewService.php';
$uid=(int)current_user()['id'];$period=(string)($_GET['goal_period']??'day');if(!in_array($period,['day','week','month','year'],true))$period='day';$trend=\App\Services\PeriodReviewService::dashboardGoalTrend(db(),$uid,$period,30);
$labels=array_map(fn($r)=>$period==='year'?date('Y',strtotime($r['period'])):($period==='month'?date('M Y',strtotime($r['period'])):($period==='week'?date('M d',strtotime($r['period'])):date('M d',strtotime($r['period'])))),$trend);$values=array_map(fn($r)=>(float)$r['achievement'],$trend);$latest=$values?end($values):null;
?>
<div class="card chart-card"><div class="section-heading"><div><h2>Review Goal Achievement</h2><div class="sub">Percentage of selected review goals marked as Hit in completed Post Reviews.</div></div><form method="get"><select name="goal_period" onchange="this.form.submit()"><option value="day" <?=$period==='day'?'selected':''?>>Day</option><option value="week" <?=$period==='week'?'selected':''?>>Week</option><option value="month" <?=$period==='month'?'selected':''?>>Month</option><option value="year" <?=$period==='year'?'selected':''?>>Year</option></select></form></div><?php if($latest!==null):?><div class="metric" style="margin-bottom:9px"><div class="label">Latest Goal Achievement</div><div class="value"><?=number_format($latest,1)?>%</div><div class="hint">Based on completed Post Reviews</div></div><?php endif;?><canvas id="reviewGoalChart"></canvas><?php if(!$trend):?><div class="sub">Complete a Post Review with goals to start the trend.</div><?php endif;?></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script nonce="<?=e(csp_nonce())?>">(function(){const el=document.getElementById('reviewGoalChart');if(!el)return;new Chart(el,{type:'line',data:{labels:<?=json_encode($labels,JSON_UNESCAPED_UNICODE)?>,datasets:[{label:'Goal Achievement',data:<?=json_encode($values)?>,tension:.25,fill:false}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false},ticks:{font:{size:8}}},y:{min:0,max:100,ticks:{callback:function(v){return v+'%';},font:{size:8}}}}}});})();</script>
